(lambda _: kAssert(kTypeOf(lambda : 42) == "Function"))(None)
(lambda _: kAssert(kTypeOf(lambda : 2 * 3) == "Function"))(None)
(lambda _: kAssert(kTypeOf(lambda x: x) == "Function"))(None)
(lambda _: kAssert(kTypeOf(lambda x: kMul(x, 2)) == "Function"))(None)
(lambda _: kAssert(kTypeOf(lambda x, y: kAdd(x, y)) == "Function"))(None)
(lambda _: kAssert(kTypeOf(lambda a, b, c: kAdd(kAdd(a, b), c)) == "Function"))(None)
(lambda _: kAssert(kTypeOf(lambda x: kAdd(kMul(x, x), 1)) == "Function"))(None)
(lambda _: kAssert(kTypeOf(lambda price: kMul(price, 1.21)) == "Function"))(None)
(lambda _: kAssert(kTypeOf(lambda _: kMul(_.get("budget"), 1.21)) == "Function"))(None)
(lambda _: kAssert(kTypeOf(lambda item: kAdd(item.get("price"), item.get("tax"))) == "Function"))(None)
(lambda _: kAssert(kTypeOf(lambda x: (doubled := kMul(x, 2), kAdd(doubled, 1))[-1]) == "Function"))(None)
(lambda _: kAssert(kTypeOf(lambda x: (x) if ((x > 0)) else (kSub(0, x))) == "Function"))(None)
(lambda _: kAssert(kEq((double := lambda x: kMul(x, 2), double(5))[-1], 10)))(None)
(lambda _: kAssert(kEq((add := lambda x, y: kAdd(x, y), add(3, 4))[-1], 7)))(None)
(lambda _: kAssert(kEq((double := lambda x: kMul(x, 2), double(2))[-1], 4)))(None)

(lambda _: kAssert(kEq((a := 1, f := lambda a: kMul(a, 2), kAdd(f(5), a))[-1], 11)))(None)
(lambda _: kAssert(kEq((a := 1, (lambda a: lambda b: kAdd(a, b))(10)(5))[-1], 15)))(None)

(lambda _: kAssert(kEq((f := lambda x: kAdd(x, 1), f__2 := lambda x: kMul(f(x), 2), f__2(1))[-1], 4)))(None)
(lambda _: kAssert(kEq((g := lambda x: (x__2 := kAdd(x, 1), x__2)[-1], g(1))[-1], 2)))(None)
(lambda _: kAssert(kEq((f := lambda x: (f__2 := lambda y: kMul(y, 3), f__2(x))[-1], f(2))[-1], 6)))(None)
(lambda _: kAssert(kEq((x := lambda q: (x__2 := kAdd(q, 1), x__2)[-1], kAdd(x(1), x(2)))[-1], 5)))(None)
